scan_regions = input('scan_regions')
exempt       = (input('exempt_assets') || {})['CKV_AWS_174'] || []

control 'CKV_AWS_174' do
  title 'Verify CloudFront Distribution Viewer Certificate is using TLS v1.2 or higher'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the aws_cloudfront_distribution resources that actually exist, read
    through the stock inspec-aws aws_cloudfront_distribution resource.
  DESC

  desc 'rationale', <<~RATIONALE
    Verify CloudFront Distribution Viewer Certificate is using TLS v1.2 or
    higher. Anchors derived from the check's encryption category, not
    reviewed control by control.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: aws_cloudfront_distribution:
    viewer_certificate/[0]/minimum_protocol_version is True
  CHECK

  desc 'fix', <<~'FIX'
    See https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/cloudfront_distribution#viewer-certificate
  FIX

  tag checkov_id:            'CKV_AWS_174'
  tag checkov_category:      'ENCRYPTION'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'value'
  tag tf_resources:          %w[aws_cloudfront_distribution]
  tag tf_docs:               'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/cloudfront_distribution#viewer-certificate'
  tag nist:                  ['SC-28', 'SC-28 (1)']
  tag nist_r4:               ['SC-28', 'SC-28 (1)']
  tag cci:                   ['CCI-001199', 'CCI-002475']
  tag ksi:                   ['KSI-SVC-CER']
  tag severity:              'high'
  tag severity_source:       'assessed'
  tag nist_source:           'category-derived'
  tag implementation_status: 'implemented'

  # Enumerated at control scope, then each asset asserted on its own. The
  # resource is an ARGUMENT to `describe`, which evaluates on the control --
  # calling it inside the block would defer it into the example.
  #
  # Every call carries aws_region: a stock resource otherwise reads only the
  # region the connection was built with, and every other region's resources
  # report as absent, which renders Not Applicable rather than unexamined.
  found = checkov_scan_regions(scan_regions).flat_map do |region|
    aws_cloudfront_distributions(aws_region: region).distribution_ids.to_a.map { |id| [id, region] }
  end

  # A plural resource whose table is built from the API response returns nil for
  # a column that does not exist, rather than raising. Passing that on gives
  # "`[:x]` must be provided" and kills the control. Blank ids are separated out
  # and asserted on below, so a wrong `ids` column is a visible failure rather
  # than a crash or a silent Not Applicable.
  unusable = found.count { |id, _r| "#{id}".strip.empty? }
  found = found.reject { |id, _r| "#{id}".strip.empty? }
  in_scope = found.reject { |id, _r| checkov_exempt?(id: id, type: 'aws_cloudfront_distribution', rules: exempt) }

  if unusable.positive?
